from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const notice=','const heading=','function save(','function footer(')))
script=defs+'''
const compact=innerWidth<=1100,cases=[];
for(const language of ['ko','en'])for(const saved of [false,true])for(const formats of [[],['json','csv','html']])for(const width of [656,904,1060]){lang=language;state=initial();state.screen='save';state.saved=saved;state.formats=new Set(formats);const f=document.createElement('div');f.className='fixture';f.style.width=width+'px';const id=`${compact?'compact':'wide'}-${language}-${saved}-${formats.length}-${width}`;f.innerHTML='<div class="page">'+save()+'</div>';f.firstChild.dataset.id=id;cases.push({id,width,viewport:innerWidth,english:language==='en',saved,formats});document.getElementById('fixtures').append(f)}
function read(){return [...document.querySelectorAll('.page')].map(e=>{const r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}};return{id:e.dataset.id,root:box(e),heading:box(e.querySelector('.page-heading')),options:box(e.querySelector('.download-options')),summary:box(e.querySelector('.summary-list')),notice:e.querySelector('.notice')?box(e.querySelector('.notice')):null,buttons:[...e.querySelectorAll('.actions button')].map(b=>({box:box(b),label:b.textContent.trim()})),title:e.querySelector('h1').textContent,description:e.querySelector('.page-heading p').textContent,checked:[...e.querySelectorAll('[data-format]:checked')].map(x=>x.dataset.format)}})}function getCases(){return cases}
'''
(o/'savepage-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'savepage-inner.html').write_text('<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="savepage-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture:not(:first-child){visibility:hidden}</style><div id="fixtures"></div><script>'+script+'</script>')
(o/'savepage.html').write_text('''<!doctype html><meta charset="utf-8"><title>SavePage · original isolation</title><button id="savepage-record">Record SavePage</button><iframe width="1000" height="950" src="savepage-inner.html"></iframe><iframe width="1400" height="950" src="savepage-inner.html" style="position:absolute;left:0;top:0;visibility:hidden"></iframe><script>document.getElementById('savepage-record').onclick=async()=>{const frames=[...document.querySelectorAll('iframe')];for(const f of frames)await f.contentDocument.fonts.ready;const rows=frames.flatMap(f=>f.contentWindow.read()),cases=frames.flatMap(f=>f.contentWindow.getCases());const res=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows,cases})});if(!res.ok)throw Error('Record failed');document.getElementById('savepage-record').textContent='SavePage recorded'}</script>''')
